  `,t.querySelectorAll(".event-choice").forEach(n=>{n.addEventListener("click",()=>a({type:"EVENT_CHOICE",choiceIndex:parseInt(n.dataset.idx)}))}),t}function bt(e,a){const t=document.createElement("div");t.className="scene-event";const o=G.find(n=>n.id===e.currentEventId),r=e.eventOutcomeText??"Nothing changes.";return t.innerHTML=`
